/**
 * Internal carrier tracking (FedEx-branded UI).
 * Numbers are generated by us until a real FedEx API is connected.
 * Store under Order.internalNotes: carrierTracking, shipmentEvents, deliveryAddress.
 */

export type ShipmentEvent = {
  code: string;
  label: string;
  detail: string;
  at: string;
  location?: string;
};

export type DeliveryAddress = {
  line1?: string;
  line2?: string | null;
  city?: string;
  state?: string;
  postal?: string;
  country?: string;
};

export type ShippingMeta = {
  carrierTracking?: string;
  carrierTrackingIssuedAt?: string;
  shipmentEvents?: ShipmentEvent[];
  deliveryAddress?: DeliveryAddress | null;
  [key: string]: unknown;
};

/** Ordered shipment steps admin can set one by one. */
export const SHIP_STEPS: {
  code: string;
  label: string;
  detail: string;
  defaultLocation: string;
}[] = [
  {
    code: 'LABEL',
    label: 'Shipping label created',
    detail: 'Vehicle assigned to transport. Tracking number issued.',
    defaultLocation: 'New York, NY',
  },
  {
    code: 'PICKED_UP',
    label: 'Picked up',
    detail: 'Vehicle collected from origin facility for worldwide transport.',
    defaultLocation: 'Origin hub',
  },
  {
    code: 'IN_TRANSIT',
    label: 'In transit',
    detail: 'Shipment is moving through the carrier network toward the delivery address.',
    defaultLocation: 'In transit',
  },
  {
    code: 'OUT_FOR_DELIVERY',
    label: 'Out for delivery',
    detail: 'Final mile: vehicle is out for delivery to the address on file.',
    defaultLocation: 'Destination area',
  },
  {
    code: 'DELIVERED',
    label: 'Delivered',
    detail: 'Shipment completed. Handover and paperwork finalized at the delivery address.',
    defaultLocation: 'Delivery address',
  },
];

export type ShipStepCode =
  | 'LABEL'
  | 'PICKED_UP'
  | 'IN_TRANSIT'
  | 'OUT_FOR_DELIVERY'
  | 'DELIVERED';

export function formatDeliveryAddress(addr?: DeliveryAddress | null): string {
  if (!addr) return '';
  return [addr.line1, addr.line2, [addr.city, addr.state, addr.postal].filter(Boolean).join(', '), addr.country]
    .filter(Boolean)
    .join(', ');
}

export function generateTrackingNumber() {
  const body = Array.from({ length: 8 }, () => Math.floor(Math.random() * 10)).join('');
  return `7946${body}`;
}

export function parseOrderMeta(raw: string | null | undefined): ShippingMeta {
  if (!raw) return {};
  try {
    return JSON.parse(raw) as ShippingMeta;
  } catch {
    return {};
  }
}

export function stringifyOrderMeta(meta: ShippingMeta) {
  return JSON.stringify(meta);
}

export function ensureTrackingOnMeta(meta: ShippingMeta, now = new Date()): ShippingMeta {
  if (meta.carrierTracking) return meta;
  const issued = now.toISOString();
  const tracking = generateTrackingNumber();
  const dest = formatDeliveryAddress(meta.deliveryAddress);
  const events: ShipmentEvent[] = [
    {
      code: 'LABEL',
      label: 'Shipping label created',
      detail: dest
        ? `Vehicle assigned to transport for delivery to ${dest}. Tracking number issued.`
        : 'Vehicle assigned to transport. Tracking number issued.',
      at: issued,
      location: 'New York, NY',
    },
  ];
  return {
    ...meta,
    carrierTracking: tracking,
    carrierTrackingIssuedAt: issued,
    shipmentEvents: events,
  };
}

/** Append a single step (manual admin control). Fills prior steps if missing. */
export function applyShipStep(
  meta: ShippingMeta,
  stepCode: ShipStepCode,
  now = new Date()
): ShippingMeta {
  const next = ensureTrackingOnMeta(meta, now);
  const events = [...(next.shipmentEvents || [])];
  const dest = formatDeliveryAddress(next.deliveryAddress);
  const iso = now.toISOString();
  const idx = SHIP_STEPS.findIndex((s) => s.code === stepCode);
  if (idx < 0) return next;

  for (let i = 0; i <= idx; i++) {
    const step = SHIP_STEPS[i];
    if (events.some((e) => e.code === step.code)) continue;

    let detail: string = step.detail;
    let location: string = step.defaultLocation;

    if (step.code === 'OUT_FOR_DELIVERY' && dest) {
      detail = `Out for delivery to ${dest}.`;
      location = dest;
    }
    if (step.code === 'DELIVERED' && dest) {
      detail = `Delivered to ${dest}. Handover and paperwork finalized.`;
      location = dest;
    }
    if (step.code === 'IN_TRANSIT' && dest) {
      detail = `In transit toward ${dest}.`;
    }
    if (step.code === 'LABEL' && dest) {
      detail = `Vehicle assigned to transport for delivery to ${dest}. Tracking number issued.`;
    }

    events.push({
      code: step.code,
      label: step.label,
      detail,
      at: iso,
      location,
    });
  }

  events.sort((a, b) => new Date(a.at).getTime() - new Date(b.at).getTime());
  return { ...next, shipmentEvents: events };
}

/** Map admin order buttons to ship steps + orderStatus. */
export function syncShipmentEvents(
  meta: ShippingMeta,
  orderStatus: string,
  now = new Date()
): ShippingMeta {
  if (orderStatus === 'PAID') return applyShipStep(meta, 'PICKED_UP', now);
  if (orderStatus === 'PROCESSING') return applyShipStep(meta, 'IN_TRANSIT', now);
  if (orderStatus === 'DELIVERED' || orderStatus === 'COLLECTED') {
    return applyShipStep(meta, 'DELIVERED', now);
  }
  return ensureTrackingOnMeta(meta, now);
}

export function currentShipmentStatus(events: ShipmentEvent[] | undefined) {
  if (!events || events.length === 0) return 'Label pending';
  return events[events.length - 1]?.label || 'In progress';
}

/** Suggested orderStatus when admin sets a ship step. */
export function orderStatusForShipStep(code: ShipStepCode): string {
  switch (code) {
    case 'LABEL':
    case 'PICKED_UP':
      return 'PAID';
    case 'IN_TRANSIT':
    case 'OUT_FOR_DELIVERY':
      return 'PROCESSING';
    case 'DELIVERED':
      return 'DELIVERED';
    default:
      return 'PAID';
  }
}
